650	async function editWorkspace(input: unknown): Promise<WorkspaceEditResult> {
651	  const reg = requireRegistry();
652	  const { id, name, color } = (input ?? {}) as { id?: unknown; name?: unknown; color?: unknown };
653	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
654	  const outcome = await reg.edit(id, {
655	    ...(typeof name === "string" ? { name } : {}),
656	    ...(typeof color === "string" ? { color } : {}),
657	  });
658	  if (!outcome.ok) return outcome;
659	  const { availability } = await availabilityOf(outcome.entry.id);
660	  // The window title shows the active workspace's name, and the tiles show the initials.
661	  refreshTitles();
662	  await broadcastState();
663	  return {
664	    ok: true,
665	    workspace: toWorkspaceView(
666	      outcome.entry,
667	      availability,
668	      null,
669	      null,
670	      syncStates.of(outcome.entry),
671	    ),
672	    savedToFolder: outcome.savedToFolder,
673	  };
674	}
675	
676	function overridableKeys(value: unknown): OverridableKey[] | null {
677	  if (!Array.isArray(value) || !value.every(isOverridableKey)) return null;
678	  return value;
679	}
680	
681	/** `settings:*` channels for the other levels (ADR 0034). The generic ones stay in settings-store. */
682	function registerSettingsScopeHandlers(): void {
683	  ipcMain.handle(IPC_CHANNELS.settingsGetScoped, (_event, scope: unknown) =>
684	    requireWorkspaceSettings().getScoped(typeof scope === "string" ? scope : "all"),
685	  );
686	  ipcMain.handle(
687	    IPC_CHANNELS.settingsSetOverride,
688	    (_event, workspaceId: unknown, key: unknown, value: unknown) =>
689	      typeof workspaceId === "string" && isOverridableKey(key)
690	        ? requireWorkspaceSettings().setOverride(workspaceId, key, value ?? null)
691	        : { ok: false, reason: "not-overridable" },
692	  );
693	  ipcMain.handle(
694	    IPC_CHANNELS.settingsResetOverrides,
695	    (_event, workspaceId: unknown, keys: unknown) => {
696	      const checked = overridableKeys(keys);
697	      return typeof workspaceId === "string" && checked
698	        ? requireWorkspaceSettings().resetOverrides(workspaceId, checked)
699	        : { ok: false, reason: "not-overridable" };
700	    },
701	  );
702	  ipcMain.handle(IPC_CHANNELS.settingsCopyToAll, (_event, workspaceId: unknown, keys: unknown) => {
703	    const checked = overridableKeys(keys);
704	    return typeof workspaceId === "string" && checked
705	      ? requireWorkspaceSettings().copyToAll(workspaceId, checked)
706	      : { ok: false, reason: "not-overridable" };
707	  });
708	  ipcMain.handle(
709	    IPC_CHANNELS.settingsResolvePending,
710	    (_event, workspaceId: unknown, decision: unknown, sha256: unknown) =>
711	      typeof workspaceId === "string" &&
712	      (decision === "use" || decision === "ignore") &&
713	      typeof sha256 === "string"
714	        ? requireWorkspaceSettings().resolvePending(workspaceId, decision, sha256)
715	        : { ok: false, reason: "nothing-pending" },
716	  );
717	}
718	
719	/**
720	 * "Change folder…": the native folder picker, then the workspace is pointed at that folder.
721	 * Relocating never moves or copies files; the rules are in `relocate.ts` and the registry.
722	 */
723	async function relocateFolder(
724	  sender: Electron.WebContents,
725	  id: unknown,
726	): Promise<WorkspaceRelocateResult> {
727	  const reg = requireRegistry();
728	  const deps = { ...activeTransactionDeps(), registry: reg };
729	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
730	  // Locked or read-only: say so now, instead of after the user picked a folder.
731	  const refused = relocateRefusal(deps, id);
732	  if (refused) return refused;
733	  const entry = reg.get(id);
734	  if (!entry) return { ok: false, reason: "unknown" };
735	
736	  const window = BrowserWindow.fromWebContents(sender);
737	  const t = createMainTranslator(getAppSettings().locale);
738	  const options: Electron.OpenDialogOptions = {
739	    title: t("dialogs.relocateWorkspace", { name: entry.name }),
740	    buttonLabel: t("dialogs.relocateWorkspaceButton"),
741	    // Where it was: a moved folder is usually next to where it used to be.
742	    defaultPath: dirname(entry.path),
743	    properties: ["openDirectory", "createDirectory"],
744	  };
745	  const picked = window
746	    ? await dialog.showOpenDialog(window, options)
747	    : await dialog.showOpenDialog(options);
748	  const chosen = picked.filePaths[0];
749	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
750	
751	  const outcome = await relocateWorkspace(deps, id, chosen);
752	  if (!outcome.ok) return outcome;
753	  // The new folder may be a synced one (Google Drive): detect it, and probe it bounded.
754	  const current = reg.get(outcome.entry.id) ?? outcome.entry;
755	  await syncStates.refresh(current);
756	  const { availability } = await availabilityOf(current.id);
757	  // The active workspace re-lists inside its transaction; any other one only needs the state.
758	  refreshTitles();
759	  await broadcastState();
760	  return {
761	    ok: true,
762	    workspace: toWorkspaceView(current, availability, null, null, syncStates.of(current)),
763	    ...(outcome.unchanged ? { unchanged: true as const } : {}),
764	  };
765	}
766	
767	export function registerWorkspaceHandlers(deps: WorkspaceHost): void {
768	  host = deps;
769	  registerSettingsScopeHandlers();
770	  ipcMain.handle(IPC_CHANNELS.workspacesList, () => listState());
771	  ipcMain.handle(IPC_CHANNELS.workspacesSwitch, (_event, id: unknown) =>
772	    typeof id === "string" ? runSwitch(id) : { ok: false, reason: "unknown" },
773	  );
774	  ipcMain.handle(IPC_CHANNELS.workspacesAdd, (event, options: unknown) =>
775	    addWorkspace(event.sender, (options ?? {}) as { activate?: unknown }),
776	  );
777	  ipcMain.handle(IPC_CHANNELS.workspacesMoveItems, (event, stamp: unknown, input: unknown) =>
